    "1d-convolution-markdown-code-9": "#include <cuda_runtime.h>\n\n__global__ void convolution_1d_kernel(\n    const float* input,\n    const float* kernel,\n    float* output,\n    int input_size,\n    int kernel_size\n) {}\n\n// input, kernel, output are device pointers (i.e. pointers to memory on the GPU)\nextern \"C\" void solve(\n    const float* input,\n    const float* kernel,\n    float* output,\n    int input_size,\n    int kernel_size\n) {\n    int output_size = input_size - kernel_size + 1;\n    int threadsPerBlock = 256;\n    int blocksPerGrid =\n        (output_size + threadsPerBlock - 1) / threadsPerBlock;\n\n    convolution_1d_kernel<<<blocksPerGrid, threadsPerBlock>>>(\n        input, kernel, output, input_size, kernel_size\n    );\n    cudaDeviceSynchronize();\n}",
